      );
    });
    test('no active jobs → exit (regardless of the ceiling)', () {
      expect(
        headlessJobDrainAction(
          hasActiveJobs: false,
          now: now,
          deadline: deadline,
        ),
        HeadlessDrainAction.exit,
      );
      expect(
        headlessJobDrainAction(
          hasActiveJobs: false,
          now: deadline.add(const Duration(hours: 1)),
          deadline: deadline,
        ),
        HeadlessDrainAction.exit,
      );
    });
