      expect(
        headlessJobDrainAction(
          hasActiveJobs: true,
          now: deadline,
          deadline: deadline,
        ),
        HeadlessDrainAction.detach,
      );
      expect(
        headlessJobDrainAction(
          hasActiveJobs: true,
          now: deadline.add(const Duration(seconds: 1)),
          deadline: deadline,
        ),
        HeadlessDrainAction.detach,
      );
    });
  });

  group(
    'headlessJobLivenessAction (the pure liveness decision, gh-1459 ask #4)',
    () {
