            id: 't1',
            name: 'bash',
            arguments: {
              'command': 'dart test --exclude-tags integration',
              'background': true,
            },
          ),
        ]),
        textTurn(
          'Started the full suite in the background. Waiting on it before '
          'writing outputs/response.md.',
        ),
      ],
    );
    final cli = AgentCli(
      config: AgentCliConfig(
        model: testModel,
