      );
      expect(reactionText, contains('exit code 0'));
      expect(job.exitCode, 0);
      expect(
        io.out.toString(),
        contains('⏳ waiting:'),
        reason: 'the drain names what it waits for (#1055 parity)',
      );
      expect(
        io.out.toString(),
