        '<system-notice>\n'
        'Job ${job.id} running · ${headlessLivenessElapsedText(elapsed)} '
        'elapsed · tail: ${tail.isEmpty ? '(no output yet)' : tail}\n'
        'Escape hatch: bash_job output ${job.id} (inspect) / '
        'bash_job stop ${job.id} (kill). Log: ${job.logPath}\n'
        '</system-notice>';
