      expect(h.livenessNotice(2), contains('10m elapsed'));
      expect(h.livenessNotice(3), contains('15m elapsed'));

      job.finish(0);
      final code = await h.run;

      expect(code, 0);
      expect(
        h.livenessRuns.length,
        3,
        reason: 'the budget holds exactly: 3 crossings, 3 notices',
      );
      h.io.close();
    },
  );
